def bell_Number(n):
    if n == 0:
        return 1
    rows = [[1]]
    for i in range(1, n + 1):
        prev_row = rows[i - 1]
        new_row = [prev_row[-1]]
        for j in range(1, i + 1):
            next_val = new_row[j - 1] + prev_row[j - 1]
            new_row.append(next_val)
        rows.append(new_row)
    return rows[n][0]

