import re

def move_num(s):
    tokens = re.findall('\\d+|\\D+', s)
    non_digits = []
    digits = []
    for token in tokens:
        if token.isdigit():
            digits.append(token)
        else:
            non_digits.append(token)
    return ''.join(non_digits) + ''.join(digits)

def largest_subset(lst, n):
    if not lst:
        return 0
    lst_sorted = sorted(lst)
    dp = [1] * len(lst_sorted)
    max_len = 1
    for i in range(len(lst_sorted)):
        for j in range(i):
            if lst_sorted[i] % lst_sorted[j] == 0:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
        max_len = max(max_len, dp[i])
    return max_len

