def get_median(lst, lst2, n):
    merged = []
    i = j = 0
    while i < n and j < n:
        if lst[i] < lst2[j]:
            merged.append(lst[i])
            i += 1
        else:
            merged.append(lst2[j])
            j += 1
    while i < n:
        merged.append(lst[i])
        i += 1
    while j < n:
        merged.append(lst2[j])
        j += 1
    total = 2 * n
    mid = total // 2
    return (merged[mid - 1] + merged[mid]) / 2

