def rgb_to_hsv(n, n2, n3):
    original_r = n
    original_g = n2
    original_b = n3
    r = original_r / 255.0
    g = original_g / 255.0
    b = original_b / 255.0
    cmax = max(r, g, b)
    cmin = min(r, g, b)
    delta = cmax - cmin
    max_val = max(original_r, original_g, original_b)
    if delta == 0:
        h = 0.0
    else:
        if original_r == max_val:
            h_part = (g - b) / delta
        elif original_g == max_val:
            h_part = (b - r) / delta
        else:
            h_part = (r - g) / delta
        if original_r == max_val:
            h = h_part % 6
        elif original_g == max_val:
            h = h_part + 2
        else:
            h = h_part + 4
        h *= 60
        h %= 360.0
    if cmax == 0:
        s = 0.0
    else:
        s = delta / cmax * 100
    v = cmax * 100
    return (h, s, v)

