import heapq

def nth_super_ugly_number(n, lst):
    heap = [1]
    seen = {1}
    primes = lst
    for _ in range(n - 1):
        current = heapq.heappop(heap)
        for p in primes:
            new_num = current * p
            if new_num not in seen:
                seen.add(new_num)
                heapq.heappush(heap, new_num)
    return heapq.heappop(heap)

