import heapq

def find_platform(lst, lst2, n):
    events = sorted(zip(lst, lst2), key=lambda x: x[0])
    heap = []
    max_platforms = 0
    for arrival, departure in events:
        while heap and heap[0] <= arrival:
            heapq.heappop(heap)
        heapq.heappush(heap, departure)
        current = len(heap)
        if current > max_platforms:
            max_platforms = current
    return max_platforms

def Sum(n):
    total = 0
    for d in str(n):
        digit = int(d)
        if digit == 0:
            continue
        div_sum = 0
        for i in range(1, digit + 1):
            if digit % i == 0:
                div_sum += i
        if digit > 5:
            if digit % 2 == 0:
                div_sum -= 2
            else:
                div_sum -= 1
        total += div_sum
    return total

