def n_common_words(s, n):
    words = s.split()
    if not words:
        return []
    first_occurrence = {}
    for idx, word in enumerate(words):
        if word not in first_occurrence:
            first_occurrence[word] = idx
    freq = {}
    for word in words:
        freq[word] = freq.get(word, 0) + 1
    unique_words = list(freq.keys())
    unique_words.sort(key=lambda x: (-freq[x], first_occurrence[x]))
    top_n = unique_words[:n]
    return [(word, freq[word]) for word in top_n]

def find_longest_conseq_subseq(lst, n):
    num_set = set(lst)
    max_length = 0
    for num in num_set:
        if num - 1 not in num_set:
            current = num
            count = 1
            while current + 1 in num_set:
                current += 1
                count += 1
            max_length = max(max_length, count)
    return max_length

