def is_Isomorphic(s, s2):
    """একটি পাইথন ফাংশন লিখুন যাচাই করতে যে দুটি প্রদত্ত স্ট্রিং একে অপরের সাথে আইসোমর্ফিক কিনা।"""
    'Translated: Write a Python function to verify whether two given strings are isomorphic to each other.'
    "\n    Args:\n        s (<class 'str'>): Example: 'paper'\n        s2 (<class 'str'>): Example: 'title'\n        \n    Returns:\n        <class 'bool'>: Example: True\n\n    Example:\n        >>> is_Isomorphic('paper', 'title')\n        True\n    "
    if len(s) != len(s2):
        return False
    s_map = {}
    s_pattern = []
    cid = 0
    for c in s:
        if c not in s_map:
            s_map[c] = cid
            cid += 1
        s_pattern.append(s_map[c])
    s2_map = {}
    s2_cid = 0
    s2_p = []
    for c in s2:
        if c not in s2_map:
            s2_map[c] = s2_cid
            s2_cid += 1
        s2_p.append(s2_map[c])
    return s_pattern == s2_p

