def modular_sum(lst, n, n2):
    m = n2
    if m == 0:
        return False
    current = set()
    for num in lst:
        rem = num % m
        if rem == 0:
            return True
        new_subs = {rem}
        for r in current:
            new_r = (r + rem) % m
            new_subs.add(new_r)
        if 0 in new_subs:
            return True
        current.update(new_subs)
    return 0 in current

def radix_sort(lst):
    if not lst:
        return []
    arr = lst.copy()
    max_num = max(arr)
    exp = 1
    while max_num // exp > 0:
        buckets = [[] for _ in range(10)]
        for num in arr:
            digit = num // exp % 10
            buckets[digit].append(num)
        arr = []
        for b in buckets:
            arr.extend(b)
        exp *= 10
    return arr

