def sqrt_root(n):
    if n < 0:
        raise ValueError('n must be non-negative')
    low, high = (0, n)
    while low <= high:
        mid = (low + high) // 2
        mid_sq = mid * mid
        if mid_sq == n:
            return mid
        elif mid_sq < n:
            low = mid + 1
        else:
            high = mid - 1
    return high

