def lbs(lst):
    n = len(lst)
    if n == 0:
        return 0
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if lst[j] < lst[i]:
                lis[i] = max(lis[i], lis[j] + 1)
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        max_lds = 0
        for j in range(i + 1, n):
            if lst[j] < lst[i]:
                max_lds = max(max_lds, lds[j])
        lds[i] = 1 + max_lds
    max_len = 0
    for i in range(n):
        max_len = max(max_len, lis[i] + lds[i] - 1)
    return max_len

