import math

def check_abundant(n):
    if n <= 1:
        return False
    sum_div = 1
    sqrt_n = int(math.sqrt(n))
    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            sum_div += i
            other = n // i
            if other != i:
                sum_div += other
    return sum_div > n

